#!/usr/bin/env python3
"""Emit sanitized local passwd/shadow metadata; never emit password fields."""
import json
import stat
import time
from pathlib import Path

PASSWD = Path("/etc/passwd")
SHADOW = Path("/etc/shadow")
COLLECTOR = "linux_local_password_policy_v1"


def signature(path):
    info = path.stat()
    if not stat.S_ISREG(info.st_mode):
        raise RuntimeError(f"not_regular:{path}")
    return (info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns)


def parse_file(path, field_count):
    records = {}
    with path.open("r", encoding="utf-8", errors="strict") as handle:
        for line_number, raw in enumerate(handle, start=1):
            line = raw.rstrip("\n")
            if not line:
                continue
            fields = line.split(":")
            if len(fields) != field_count or not fields[0]:
                raise ValueError(f"invalid_record:{path}:{line_number}")
            if fields[0] in records:
                raise ValueError(f"duplicate_user:{path}:{line_number}")
            records[fields[0]] = fields
    return records


def stable_pair():
    for _ in range(3):
        before = (signature(PASSWD), signature(SHADOW))
        passwd = parse_file(PASSWD, 7)
        shadow = parse_file(SHADOW, 9)
        after = (signature(PASSWD), signature(SHADOW))
        if before == after:
            return passwd, shadow
    raise RuntimeError("account_files_changed_during_read")


def optional_nonnegative(value):
    if value == "":
        return None
    parsed = int(value, 10)
    if parsed < 0:
        raise ValueError("negative_shadow_aging_value")
    return parsed


def emit(observed, collector_status, record_status, **fields):
    event = {
        "collector_schema": 1,
        "collector": COLLECTOR,
        "collector_status": collector_status,
        "observed_at_epoch": observed,
        "record_status": record_status,
    }
    event.update(fields)
    print(json.dumps(event, ensure_ascii=True, separators=(",", ":"), sort_keys=True), flush=True)


def main():
    observed = int(time.time())
    try:
        passwd, shadow = stable_pair()
    except (OSError, UnicodeError, ValueError, RuntimeError) as error:
        emit(observed, "error", "collector_error", error_class=type(error).__name__)
        return

    for user in sorted(set(passwd) | set(shadow)):
        passwd_row = passwd.get(user)
        shadow_row = shadow.get(user)
        if passwd_row is None:
            emit(observed, "ok", "missing_passwd", user=user)
            continue
        try:
            uid = int(passwd_row[2], 10)
            gid = int(passwd_row[3], 10)
            if uid < 0 or gid < 0:
                raise ValueError("negative_identity")
        except ValueError:
            emit(observed, "ok", "parse_error", user=user)
            continue
        common = {
            "user": user,
            "uid": uid,
            "gid": gid,
            "shell": passwd_row[6],
            "passwd_shadow_marker": 1 if passwd_row[1] == "x" else 0,
        }
        if shadow_row is None:
            emit(observed, "ok", "missing_shadow", **common)
            continue
        try:
            last_change_day, min_days, max_days, warn_days, inactive_days, account_expire_day = [
                optional_nonnegative(value) for value in shadow_row[2:8]
            ]
        except ValueError:
            emit(observed, "ok", "parse_error", **common)
            continue
        secret = shadow_row[1]
        if secret == "":
            state = "empty"
        elif secret.startswith("!"):
            state = "exclamation_disabled"
        elif secret.startswith("*"):
            state = "asterisk_marker"
        else:
            state = "nonempty_unclassified"
        empty = 1 if secret == "" else 0
        disabled = 1 if secret.startswith(("!", "*")) else 0
        del secret
        emit(
            observed,
            "ok",
            "ok",
            shadow_password_state=state,
            shadow_password_empty=empty,
            unix_password_disabled=disabled,
            last_change_day=last_change_day,
            min_days=min_days,
            max_days=max_days,
            warn_days=warn_days,
            inactive_days=inactive_days,
            account_expire_day=account_expire_day,
            **common,
        )


if __name__ == "__main__":
    main()
